public 
enum AudrenFfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidInput(reason: String
    )
    case Crypto(reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AudrenFfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAudrenFfiError: FfiConverterRustBuffer {
    typealias SwiftType = AudrenFfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AudrenFfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Crypto(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AudrenFfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidInput(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Crypto(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


